\begin{tikzpicture}[>=stealth,font=\Large]
\path[use as bounding box] (-5.8,-5.8) rectangle (5.8,5.8);
\draw[step=1,gray!35,thin] (-5,-5) grid (5,5);
\draw[<->] (-5.4,0)--(5.4,0) node[right] {$x$};
\draw[<->] (0,-5.4)--(0,5.4) node[above] {$y$};
\foreach \v in {-5,-4,-3,-2,-1,1,2,3,4,5}{\draw (\v,.1)--(\v,-.1) node[below] {$\v$};\draw (.1,\v)--(-.1,\v) node[left] {$\v$};}
\begin{scope}\clip (-5,-5) rectangle (5,5);
\draw[blue,thick,<->,domain=-2:3,samples=2] plot (\x,{2*\x-1});
\fill[blue] (0,-1) circle (2pt);
\fill[blue] (1,1) circle (2pt);
\fill[blue] (2,3) circle (2pt);
\fill[blue] (3,5) circle (2pt);
\end{scope}
\end{tikzpicture}

